"use strict";(globalThis.webpackChunkmobile=globalThis.webpackChunkmobile||[]).push([[5360],{1075(e,t,n){n.r(t),n.d(t,{assets:()=>l,contentTitle:()=>s,default:()=>d,frontMatter:()=>r,metadata:()=>i,toc:()=>c});const i=JSON.parse('{"id":"Jetpack Compose/Dynamic UI/60 Pickers & Menus/Pickers","title":"DatePicker and TimePicker","description":"-","source":"@site/docs/100. Jetpack Compose/20. Dynamic UI/60 Pickers & Menus/30. Pickers.mdx","sourceDirName":"100. Jetpack Compose/20. Dynamic UI/60 Pickers & Menus","slug":"/Jetpack Compose/Dynamic UI/60 Pickers & Menus/Pickers","permalink":"/mobile/docs/Jetpack Compose/Dynamic UI/60 Pickers & Menus/Pickers","draft":false,"unlisted":false,"editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/docs/100. Jetpack Compose/20. Dynamic UI/60 Pickers & Menus/30. Pickers.mdx","tags":[],"version":"current","sidebarPosition":30,"frontMatter":{"title":"DatePicker and TimePicker"},"sidebar":"tutorialSidebar","previous":{"title":"ExposedDropdownMenuBox","permalink":"/mobile/docs/Jetpack Compose/Dynamic UI/60 Pickers & Menus/exposed-dropdown-moon"},"next":{"title":"1. Making UI React","permalink":"/mobile/docs/Jetpack Compose/Reactive UI/ClassroomCheckIn"}}');var a=n(4848),o=n(8453);const r={title:"DatePicker and TimePicker"},s=void 0,l={},c=[{value:"title: DatePicker and TimePicker",id:"title-datepicker-and-timepicker",level:2}];function m(e){const t={admonition:"admonition",code:"code",h1:"h1",h2:"h2",hr:"hr",p:"p",pre:"pre",...(0,o.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"title-datepicker-and-timepicker",children:"title: DatePicker and TimePicker"}),"\n",(0,a.jsx)(t.h1,{id:"-houston-when-is-the-launch--date--time-pickers-in-compose-",children:"\ud83d\udc68\u200d\ud83d\ude80 Houston, When is the Launch? \ud83d\udcc5 Date & Time Pickers in Compose \ud83d\udcbb"}),"\n",(0,a.jsx)(t.p,{children:"Building a robust time-selection interface in Jetpack Compose requires orchestrating state across multiple dialogs. Below is a fully functional Mars Mission Control application that guides the user through selecting a date, a time, and confirming the launch sequence."}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-kotlin",children:'@OptIn(ExperimentalMaterial3Api::class)\n@Composable\nfun MarsMissionControlApp() {\n    var scheduledLaunch by remember { mutableStateOf<String?>(null) }\n\n    var showDatePicker by remember { mutableStateOf(false) }\n    var showTimePicker by remember { mutableStateOf(false) }\n    var showConfirmDialog by remember { mutableStateOf(false) }\n\n    var tempDateMillis by remember { mutableStateOf<Long?>(null) }\n    var tempHour by remember { mutableStateOf(0) }\n    var tempMinute by remember { mutableStateOf(0) }\n\n    Scaffold(\n        topBar = {\n            TopAppBar(\n                title = { Text("Centrum Lot\xf3w na Marsa") },\n                colors = TopAppBarDefaults.topAppBarColors(\n                    containerColor = MaterialTheme.colorScheme.primaryContainer,\n                    titleContentColor = MaterialTheme.colorScheme.onPrimaryContainer\n                )\n            )\n        },\n        floatingActionButton = {\n            FloatingActionButton(onClick = { showDatePicker = true }) {\n                Icon(Icons.Default.Add, contentDescription = "Zaplanuj start")\n            }\n        }\n    ) { padding ->\n        MissionDashboard(\n            modifier = Modifier.padding(padding),\n            launchDate = scheduledLaunch\n        )\n\n        if (showDatePicker) {\n            LaunchDatePickerDialog(\n                onDateSelected = { millis ->\n                    tempDateMillis = millis\n                    showDatePicker = false\n                    showTimePicker = true\n                },\n                onDismiss = { showDatePicker = false }\n            )\n        }\n\n        if (showTimePicker) {\n            LaunchTimePickerDialog(\n                onTimeSelected = { hour, minute ->\n                    tempHour = hour\n                    tempMinute = minute\n                    showTimePicker = false\n                    showConfirmDialog = true\n                },\n                onDismiss = { showTimePicker = false }\n            )\n        }\n\n        if (showConfirmDialog && tempDateMillis != null) {\n            val formattedDateTime = formatDateTime(tempDateMillis!!, tempHour, tempMinute)\n\n            ConfirmLaunchDialog(\n                dateTimeText = formattedDateTime,\n                onConfirm = {\n                    scheduledLaunch = formattedDateTime\n                    showConfirmDialog = false\n                },\n                onDismiss = { showConfirmDialog = false }\n            )\n        }\n    }\n}\n\n@Composable\nfun MissionDashboard(modifier: Modifier = Modifier, launchDate: String?) {\n    Column(\n        modifier = modifier\n            .fillMaxSize()\n            .padding(16.dp),\n        horizontalAlignment = Alignment.CenterHorizontally\n    ) {\n        Card(\n            modifier = Modifier.fillMaxWidth(),\n            elevation = CardDefaults.cardElevation(defaultElevation = 4.dp)\n        ) {\n            Column(\n                modifier = Modifier.padding(24.dp),\n                horizontalAlignment = Alignment.CenterHorizontally\n            ) {\n                Icon(\n                    imageVector = Icons.Default.DateRange,\n                    contentDescription = null,\n                    modifier = Modifier.size(48.dp),\n                    tint = MaterialTheme.colorScheme.primary\n                )\n                Spacer(modifier = Modifier.height(16.dp))\n                Text(\n                    text = "Status Nast\u0119pnej Misji:",\n                    style = MaterialTheme.typography.titleMedium\n                )\n                Spacer(modifier = Modifier.height(8.dp))\n                Text(\n                    text = launchDate ?: "Brak zaplanowanych lot\xf3w",\n                    style = MaterialTheme.typography.headlineSmall,\n                    color = if (launchDate != null) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onSurfaceVariant\n                )\n            }\n        }\n    }\n}\n\n@OptIn(ExperimentalMaterial3Api::class)\n@Composable\nfun LaunchDatePickerDialog(\n    onDateSelected: (Long) -> Unit,\n    onDismiss: () -> Unit\n) {\n    val datePickerState = rememberDatePickerState()\n\n    DatePickerDialog(\n        onDismissRequest = onDismiss,\n        confirmButton = {\n            TextButton(\n                onClick = {\n                    datePickerState.selectedDateMillis?.let { onDateSelected(it) }\n                }\n            ) {\n                Text("Dalej")\n            }\n        },\n        dismissButton = {\n            TextButton(onClick = onDismiss) { Text("Przerwij") }\n        }\n    ) {\n        DatePicker(state = datePickerState)\n    }\n}\n\n@OptIn(ExperimentalMaterial3Api::class)\n@Composable\nfun LaunchTimePickerDialog(\n    onTimeSelected: (Int, Int) -> Unit,\n    onDismiss: () -> Unit\n) {\n    val timePickerState = rememberTimePickerState()\n\n    // TimePicker w Material 3 nie ma gotowego "TimePickerDialog",\n    // wi\u0119c standardow\u0105 praktyk\u0105 jest opakowanie go w AlertDialog\n    AlertDialog(\n        onDismissRequest = onDismiss,\n        title = { Text("Wybierz godzin\u0119 zap\u0142onu") },\n        text = {\n            // Kontener centruj\u0105cy TimePicker\n            Box(contentAlignment = Alignment.Center, modifier = Modifier.fillMaxWidth()) {\n                TimePicker(state = timePickerState)\n            }\n        },\n        confirmButton = {\n            TextButton(\n                onClick = { onTimeSelected(timePickerState.hour, timePickerState.minute) }\n            ) {\n                Text("Dalej")\n            }\n        },\n        dismissButton = {\n            TextButton(onClick = onDismiss) { Text("Cofnij") }\n        }\n    )\n}\n\n@Composable\nfun ConfirmLaunchDialog(\n    dateTimeText: String,\n    onConfirm: () -> Unit,\n    onDismiss: () -> Unit\n) {\n    AlertDialog(\n        onDismissRequest = onDismiss,\n        title = { Text("Potwierd\u017a Sekwencj\u0119 Zap\u0142onu") },\n        text = { Text("Czy na pewno chcesz zaplanowa\u0107 start na:\\n\\n$dateTimeText?") },\n        confirmButton = {\n            Button(onClick = onConfirm) {\n                Text("Potwierd\u017a Start")\n            }\n        },\n        dismissButton = {\n            TextButton(onClick = onDismiss) {\n                Text("Anuluj")\n            }\n        }\n    )\n}\n\nfun formatDateTime(millis: Long, hour: Int, minute: Int): String {\n    val date = Date(millis)\n    val dateFormat = SimpleDateFormat("dd MMM yyyy", Locale.getDefault())\n    val formattedDate = dateFormat.format(date)\n\n    // %02d gwarantuje, \u017ce jednocyfrowe godziny/minuty b\u0119d\u0105 mia\u0142y wiod\u0105ce zero (np. 09:05 zamiast 9:5)\n    val formattedTime = String.format("%02d:%02d", hour, minute)\n\n    return "$formattedDate o godzinie $formattedTime"\n}\n'})}),"\n",(0,a.jsx)(t.admonition,{type:"warning",children:(0,a.jsx)(t.p,{children:"Thought Provocation: How does the application remember the selected date while the user is busy spinning the time dial, considering both the Date and Time dialog components are completely stateless?"})}),"\n",(0,a.jsx)(t.p,{children:'Dissecting the Code: The 4W2H ModelTo understand how our DatePicker and TimePicker cooperate without collapsing into a black hole of missing data, we will analyze the architecture according to our 4W2H model.The Domain (WHAT): We are processing information in the form of The Sticky Note (Primitives). The user\'s selections are just short, simple pieces of information. We capture a Long for the date in milliseconds and Int values for the hour and minute before formatting them into a final String.   State & Storage (WHERE): The data lives in The Pocket (Local Variables). The MarsMissionControlApp component acts as our master chef, keeping variables like tempDateMillis and showTimePicker safely in its apron pocket. The child components (the dialogs) are entirely stateless and only report back up to the parent when an action occurs.   Evaluation Strategies (WHEN): The application relies on The Lazy Paradigm (The Drive-Thru) for rendering the UI. The heavy components, like LaunchTimePickerDialog, do nothing until the application explicitly asks for them. The system waits for showTimePicker = true to "fry" that specific UI element on demand, saving memory.   Data Flow (WHO): The UI interaction is driven by the Push Model (The Sushi Conveyor Belt). The application sets up asynchronous listeners (like onDateSelected) and waits. When the user confirms a date, the external world "pushes" that new event to the parent component.   Reactivity (HOW): The UI knows about changes via The PA System (State / Public Address System). We wrap our variables in mutableStateOf. When scheduledLaunch is assigned a new formatted date, the chef shouts through the loudspeaker, and the application\'s interface instantly and automatically replaces the item on the menu across the screen.   Lifecycle (HOW LONG): Currently, our mission variables use Short-term Memory (Volatile memory). They are like an order the waiter keeps only in their head. Because we used standard remember, if the tablet is rotated horizontally during the time selection process, the activity restarts, the waiter trips, and the selected date is lost forever.   Compose vs. XML: A Leap in EvolutionIn the older Android paradigm using Kotlin and XML, implementing a sequential Date and Time picker was a notoriously fragile process. You had to instantiate a DatePickerDialog, implement a rigid OnDateSetListener, and inside that listener, manually trigger a completely separate TimePickerDialog with its own OnTimeSetListener. You were forced to manipulate Java Calendar objects at every step, and finally, manually push the result to a layout using findViewById(R.id.textView).text = ....In Jetpack Compose, the UI is purely a reflection of state. Instead of chaining callbacks that manually open dialogs, we simply flip boolean switches (showDatePicker = true, showTimePicker = true). The declarative nature of Compose reads exactly like a standard if/else flowchart, making complex UI logic vastly easier to trace and debug.Mission CheckWhy are DatePicker and TimePicker wrapped inside if statements checking boolean state variables rather than being instantiated directly like standard UI buttons?According to the 4w2h model, how would you upgrade the tempDateMillis variable from "Short-term Memory" so it survives a device rotation?What is the role of state hoisting (passing onDateSelected lambdas up to the parent) in preventing the child dialogs from managing their own data?How do you envision implementing a rollback feature if the user decides to cancel their time selection and return to the date picker?'})]})}function d(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(m,{...e})}):m(e)}},8453(e,t,n){n.d(t,{R:()=>r,x:()=>s});var i=n(6540);const a={},o=i.createContext(a);function r(e){const t=i.useContext(o);return i.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:r(e.components),i.createElement(o.Provider,{value:t},e.children)}}}]);